import java.text.NumberFormat;
import java.util.Scanner;
public class JIfElseWages1
{
	public static void main (String[] args)
	{
		//Khatwa 1: Ta'reef al-mutaghayirat allati nahtaajuha li-hadha al-barnamij
		final double RATE = 8.25; 
		final int STANDARD = 40; 
		double wage = 0.0;
		//Khatwa 2: Aqra' 'adad al-saaat allati amalaha al-muwazzaf
		Scanner scan = new Scanner (System.in);
		System.out.println("Adkhil 'adad al-saaat allati amalaha al-muwazzaf: ");
		int hours = scan.nextInt();
		scan.close();
		//Khatwa 3: Adfa' al-saaat al-izafiyya bi nisf al-mablagh 'ala al-mu'addal al-'adi
		if (hours > STANDARD) {
			wage = STANDARD * RATE + (hours-STANDARD) * (RATE * 1.5);
		} else {
			wage = hours * RATE;
		}
		//Khatwa 4: Atba' al-ajr al-muhasib
		NumberFormat fmt = NumberFormat.getCurrencyInstance();
		System.out.println("Ujr: " + fmt.format(wage));
	}
}
